/**
 * Regenerate src/rpc/typert.generated.js from DESCRIPTORS and the service
 * implementation.
 *
 * The published manifest (src/rpc/typert.js) imports the generated array, so
 * the 66 member signatures cannot drift from the descriptors. test/rpc-contract
 * also compares the two, which makes a hand edit to the generated file fail
 * instead of silently shipping.
 *
 * Usage: node scripts/gen-typert.mjs [--check]
 */
import fs from "node:fs";
import path from "node:path";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import HarborService from "../src/index.js";
import { DESCRIPTORS } from "../src/rpc/descriptors.js";
import { deriveMembers } from "../src/rpc/typert-members.js";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const target = join(root, "src/rpc/typert.generated.js");
const members = deriveMembers(DESCRIPTORS, HarborService.prototype);

const render = (entries) =>
  [
    "// Generated by scripts/gen-typert.mjs from src/rpc/descriptors.js.",
    "// Do not edit by hand: run node scripts/gen-typert.mjs instead.",
    "export const MEMBERS = [",
    ...entries.map(
      (entry) => "  { kind: \"method\", name: " + JSON.stringify(entry.name) + ", signature: " + JSON.stringify(entry.signature) + " },"
    ),
    "];",
    "",
  ].join("\n");

const content = render(members);
if (process.argv.includes("--check")) {
  const current = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : "";
  if (current !== content) {
    console.error("typert.generated.js is stale; run node scripts/gen-typert.mjs");
    process.exit(1);
  }
  console.log("typert: " + members.length + " members up to date");
  process.exit(0);
}

fs.writeFileSync(target, content);
console.log("typert: wrote " + members.length + " members to src/rpc/typert.generated.js");
